// Some portions generated by Codex
import assert from "node:assert/strict";
import test from "node:test";
import { requiresManualRepositorySearch, exactSearchResource } from "../../../main/frontend/graph-explorer/repository-search.ts";
import { fetchRepositorySize } from "../../../main/frontend/graph-explorer/transport.ts";

test("only a known small repository allows the Enter fallback", () => {
  for (const count of [null, undefined, -1, NaN, Infinity, 100001, 1.5]) {
    assert.equal(requiresManualRepositorySearch(count), true, String(count));
  }
  for (const count of [0, 99999, 100000]) assert.equal(requiresManualRepositorySearch(count), false);
});

test("exact resources retain direct lookup, while labels and prefixed names do not", () => {
  assert.equal(exactSearchResource("https://example.org/a"), "https://example.org/a");
  assert.equal(exactSearchResource("<urn:example:a>"), "urn:example:a");
  assert.equal(exactSearchResource("<_:alice>"), "<_:alice>");
  for (const value of ["Person", "foaf:Person", "http://example.org/a> ?s ?p ?o", ""]) {
    assert.equal(exactSearchResource(value), undefined);
  }
});

test("size request is statement-only, non-cached and tied to the expected server", async () => {
  const original = globalThis.fetch;
  globalThis.fetch = async (url, options) => {
    assert.equal(url, "/wb/repositories/repo/graph?search-size=true");
    assert.equal(options.cache, "no-store");
    assert.equal(options.headers.accept, "application/json");
    return new Response('{"size":100001}', {headers: {"X-Workbench-Server-Identity":"server-a"}});
  };
  try { assert.equal(await fetchRepositorySize("/wb/repositories/repo/graph", "server-a"), 100001); }
  finally { globalThis.fetch = original; }
});

test("malformed, failed, negative and cross-server size responses are unknown", async () => {
  const original = globalThis.fetch;
  try {
    for (const body of ['{}', '{"size":null}', '{"size":-1}', '{"size":"1"}', '{"size":1.5}', 'bad json']) {
      globalThis.fetch = async () => new Response(body, {headers: {"X-Workbench-Server-Identity":"server-a"}});
      assert.equal(await fetchRepositorySize("/graph", "server-a"), null);
    }
    globalThis.fetch = async () => new Response('{"size":1}', {headers: {"X-Workbench-Server-Identity":"server-b"}});
    assert.equal(await fetchRepositorySize("/graph", "server-a"), null);
    globalThis.fetch = async () => new Response('unavailable', {status:503});
    assert.equal(await fetchRepositorySize("/graph", "server-a"), null);
    globalThis.fetch = async () => { throw new TypeError("network failed"); };
    assert.equal(await fetchRepositorySize("/graph", "server-a"), null);
  } finally { globalThis.fetch = original; }
});

test("a hung size probe times out as unknown", async (t) => {
  t.mock.timers.enable({apis: ["setTimeout"]});
  const original = globalThis.fetch;
  let requestSignal;
  globalThis.fetch = async (_url, {signal}) => {
    requestSignal = signal;
    return new Promise((_resolve, reject) => signal?.addEventListener("abort", () => reject(signal.reason), {once:true}));
  };
  try {
    const result = fetchRepositorySize("/graph", "server-a");
    t.mock.timers.tick(5000);
    assert.equal(requestSignal?.aborted, true);
    assert.equal(await result, null);
  } finally { globalThis.fetch = original; }
});
